bounded_host_request.command:
set -euo pipefail
stage="$(mktemp -d /tmp/gaybbs-two-topic-url-XXXXXX)"
trap 'rm -rf "$stage"' EXIT
docker cp deploy-gaybbs-1:/app/repairTwoVideoChatPinnedEntries.mjs "$stage/base.mjs"
node - "$stage/base.mjs" "$stage/fixed.mjs" <<'NODE'
const fs=require('node:fs');
const original=fs.readFileSync(process.argv[2],'utf8');
const old=/callback_data\s*:\s*buttonCallback\s*,\s*style\s*:\s*["']primary["']/g;
const matches=[...original.matchAll(old)];
if(matches.length!==3)process.exit(81);
const fixed=original.replace(old,'url: "https://t.me/GayBBS_bot?start=p_" + token');
if(fixed===original||fixed.includes('callback_data: buttonCallback'))process.exit(82);
fs.writeFileSync(process.argv[3],fixed,{mode:0o600});
NODE
node --check "$stage/fixed.mjs"
docker exec deploy-gaybbs-1 sh -lc 'test "$GAYBBS_PUBLIC_MENU_RELEASE" = enabled' || exit 83
docker exec -i deploy-gaybbs-1 node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module - < "$stage/fixed.mjs"
echo TWO_TOPIC_URL_PATCH_DRY_RUN_PASS
